import json, pathlib, html, shutil
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
root=pathlib.Path.cwd(); public=root/'apps/web/public'; out=root/'output/pdf/ai-passport-evaluation.pdf'; out.parent.mkdir(parents=True,exist_ok=True)
data=lambda name:json.loads((public/'data'/name).read_text(encoding='utf-8'))
ai=data('ai-evaluation.json'); graph=data('evidence-graph.json'); chain=data('ai-chain-evidence.json'); protocol=data('protocol-evaluation.json'); security=data('security-evaluation.json'); mcp=data('graph-mcp-evaluation.json')
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='TitleAI',fontName='Helvetica-Bold',fontSize=30,leading=34,textColor=colors.HexColor('#225b4b'),spaceAfter=18)); styles.add(ParagraphStyle(name='BodyAI',fontSize=10.5,leading=15,textColor=colors.HexColor('#182825'),spaceAfter=10)); styles.add(ParagraphStyle(name='SmallAI',fontSize=8.5,leading=12,textColor=colors.HexColor('#596b66'),spaceAfter=8))
story=[]
def para(text,style='BodyAI'):story.append(Paragraph(text,styles[style]))
def title(t):para(t,'TitleAI')
def table(rows,widths):
 rows=[[Paragraph(html.escape(str(c)),styles['SmallAI']) for c in row] for row in rows];t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf3ef')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),1,colors.HexColor('#225b4b')),('LINEBELOW',(0,1),(-1,-1),.4,colors.HexColor('#dbe4e0')),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.append(t);story.append(Spacer(1,14))
def footer(canvas,doc):canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#596b66'));canvas.drawString(42,25,'AI Passport | Built by Ajnas NB | passport.ajnasnb.com');canvas.drawRightString(A4[0]-42,25,str(doc.page))
title('AI Passport');para('Useful AI tasks with selected memory and connected evidence.','Heading2');para('Live: <link href="https://passport.ajnasnb.com">passport.ajnasnb.com</link><br/>Public source: <link href="https://github.com/AjnasNB/app-passport">github.com/AjnasNB/app-passport</link><br/>Evaluation date: '+html.escape(ai['completed_at'][:10]))
table([['Evidence','Measured result'],['Real hosted AI and gate cases',f"{ai['passed']} / {ai['total']}"],['Pinned real tool artifacts / controlled MCP calls',f"{protocol['passed']} / {protocol['total']}"],['Local SDK, graph, API and orchestration checks',f"{security['passed']} / {security['total']}"],['Independent graph MCP path / truncation checks',f"{mcp['passed']} / {mcp['total']}"],['Graph structure',f"{len(graph['nodes'])} nodes, {len(graph['edges'])} edges"],['Current signed graph entities',chain.get('graph_count',len(chain['graph_records']))]], [265,245])
para('The coding handoff generates a bounded release guard and passes six deterministic boundary cases. India number tutor calculates exact paise and lakh/crore values. UPI Safety Quest is a playable three-round learning game. The AI explanations use real Cloudflare-hosted Llama 3.2 3B inference. Hosted model weights are not attested.')
para('These are project-run demonstrations on public or synthetic inputs. They do not establish customer adoption, an independent security audit, universal model correctness, or proof of inference computation. Both demonstration wallets are project controlled.','SmallAI')
story.append(PageBreak());title('The working flow')
for h,b in [('Select a task','Choose coding, number learning or the safety game. No wallet or account is required.'),('Read current evidence','Read the signed graph from Tiramisu, verify complete manifest membership, accepted authors and entity-index bindings.'),('Bind the original sources','Read actual public source bytes, check their digests, validate the Qarinah packet and recompute its selected repository snapshot.'),('Check current admission','Require current accepted context and runtime reviews. Withdrawn, expired, modified or stale evidence blocks the model call.'),('Run bounded tools and AI','Run deterministic arithmetic or scoring, select compact cited memory, reserve a free demo allowance and call the hosted model.'),('Validate and trace the output','Generated guards are interpreted and tested, never executed as arbitrary code. Numeric statements come only from the calculator. Inspect source links and download a receipt.')]:para(h,'Heading2');para(b)
para('A Hindi model test produced a wrong conversion during development. The corrected flow renders deterministic numeric results separately and withholds model commentary containing unchecked numerical claims. Provenance alone does not guarantee factual accuracy.','SmallAI')
story.append(PageBreak());title('Live AI evaluations')
rows=[['Task / condition','HTTP','Inference','Result']]
for r in ai['results']:rows.append([r['input']['task']+' / '+r['input'].get('contextCase',r['input'].get('language','current')),r['http_status'],'Yes' if r['result'].get('inference_run') else 'No','Passed' if r['passed'] else 'Failed'])
table(rows,[280,50,85,95]);coding=next(r['result'] for r in ai['results'] if r['input']['task']=='coding' and r['result'].get('allowed'))
para('Coding memory selection','Heading2');para(f"Selected memory: {coding['memory_chars']:,} characters. Full Qarinah packet: {coding['full_packet_chars']:,} characters. Selected decision events: {len(coding['selected_event_ids'])}. This compares payload sizes; token estimates use chars/4 and are not an exact tokenizer benchmark.")
para('Tested public tool artifacts','Heading2');tools=data('tools.json');table([['Artifact','Pinned version','Protocol call']]+[[t['descriptor']['name'],t['descriptor']['version'],'Passed' if any(r['id']==t['id'] and r['passed'] for r in protocol['results']) else 'See report'] for t in tools],[255,140,115])
story.append(PageBreak());title('Why Arkiv and how to reproduce')
para('Arkiv stores shared, attributable, queryable evidence with creator and expiry metadata. Another reader can retrieve current review and withdrawal state through its own provider, without this website backend. Consumers choose their accepted issuers and reviewers. A conventional database remains sufficient for a single operator’s calculator or chat; Arkiv is useful here for interoperable evidence, not for doing arithmetic or inference.')
para('The graph is an application layer over Arkiv entities. Nodes, edges and a complete root manifest are separately signed. Traversal runs in the SDK, not native Cypher. Storage is 30 days and signed validity is 14 days, so the operator must renew evidence. RPC chain metadata and query completeness remain provider dependencies.')
para('Independent readers','Heading2');para('Install /downloads/app-passport-sdk-0.2.1.tgz. Read /data/policy.json and /data/graph-config.json, then use readGraph(connection, graphDigest) and traverseGraph(graph, "app:coding", {depth:4}). The included MCP bridge exposes trace_evidence through stdio. Its tested consumer uses the raw Tiramisu RPC, without the website or operator quota secret.')
para('Project reproduction','Heading2');para('npm ci --ignore-scripts<br/>npm run build<br/>npm run typecheck<br/>npm test<br/>npx tsx scripts/evaluate-ai.ts<br/>npx tsx scripts/test-graph-mcp.ts')
para('Free demo boundaries','Heading2');para('At most forty model attempts per UTC day, with three run requests per minute per IP. Source memory is limited to 10,000 characters and output to 420 model tokens. The calculator and game work without inference. Readers require no Web3 tokens; writers use free Tiramisu test tokens. No mainnet transaction or paid plan upgrade is required by this demo.')
para('Primary references','Heading2');para('<link href="https://docs.arkiv.network/json-rpc/querying-data/">Arkiv queries</link> · <link href="https://developers.cloudflare.com/workers-ai/models/llama-3.2-3b-instruct/">Actual model</link> · <link href="https://www.npci.org.in/fraud-awareness">NPCI guidance</link><br/><link href="https://passport.ajnasnb.com/data/ai-evaluation.json">AI receipts</link> · <link href="https://passport.ajnasnb.com/data/ai-chain-evidence.json">Signed chain evidence</link> · <link href="https://github.com/AjnasNB/app-passport/blob/main/ARCHITECTURE.md">Complete architecture</link>','SmallAI')
SimpleDocTemplate(str(out),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=42,bottomMargin=44,title='AI Passport evaluation',author='Ajnas NB').build(story,onFirstPage=footer,onLaterPages=footer)
shutil.copy2(out,public/'downloads/ai-passport-evaluation.pdf');print(json.dumps({'pdf':str(out),'ai_cases':ai['total']}))
